B.a_U=s(["Obe skali sta logaritemski in pokrivata eno dekado: oznaka 12 pomeni 1,2, 12, 120 ali 1200.","Velikostni red rezultata oceni na pamet in decimalno vejico postavi sam.","Notranja skala je hkrati \u010das v minutah; ob njej so napisane ure (npr. 1:30 = 90 min).","Indeks \u25b260 (RATE) je 60 minut oziroma ena ura, indeks SEC (pri 36) je 3600 sekund oziroma ena ura.","Vsaka nastavitev diska je razmerje: vsi pari \u0161tevil, ki stojijo drug nad drugim, imajo enako razmerje."],t.s)
B.a5V=s(["Oznaka 15 na notranji skali je lahko 1,5 min, 15 min ali 150 min (2:30).","Pri letu, dolgem pribli\u017eno dve uri, je pravilno branje 150 min."],t.s)
B.Th=new A.fT("Branje skal","Zunanja skala je fiksna, notranja je na vrtljivem disku.",!0,B.a_U,B.a5V,null)
B.a1V=s(["Na notranji skali poi\u0161\u010di \u010das leta v minutah.",u.Z,"Nad indeksom \u25b260 preberi hitrost na uro na zunanji skali."],t.s)
B.a23=s(["Med dvema to\u010dkama je 45 NM, preleteli smo ju v 30 min.","30 na notranji skali postavi pod 45 na zunanji.","Nad \u25b260 preberi 90."],t.s)
B.Tj=new A.fT("Hitrost iz razdalje in \u010dasa","GS = razdalja / \u010das",!0,B.a1V,B.a23,"GS = 90 kt")
B.a6U=s([u.k,"Na zunanji skali poi\u0161\u010di razdaljo.","Pod njo na notranji skali preberi \u010das v minutah."],t.s)
B.a5l=s(["GS 110 kt, do cilja je 38 NM.","\u25b260 postavi pod 11 (110 kt).","Pod 38 na zunanji skali preberi pribli\u017eno 20,7."],t.s)
B.Tl=new A.fT("\u010cas leta za dano razdaljo","\u010das = razdalja / GS",!0,B.a6U,B.a5l,"\u010cas \u2248 21 min")
B.a5N=s([u.k,"Na notranji skali poi\u0161\u010di \u010das v minutah.","Nad njim na zunanji skali preberi preleteno razdaljo."],t.s)
B.a_S=s(["Jadralno letalo leti s 95 km/h (GS). Koliko preleti v 25 min?","\u25b260 postavi pod 95.","Nad 25 na notranji skali preberi pribli\u017eno 39,6."],t.s)
B.Tm=new A.fT("Razdalja v danem \u010dasu","razdalja = GS \xd7 \u010das",!0,B.a5N,B.a_S,"Razdalja \u2248 40 km")
B.a6k=s(["Na notranji skali poi\u0161\u010di \u010das v sekundah.",u.Z,"Nad indeksom SEC (pri 36) preberi hitrost na uro."],t.s)
B.a2v=s(["Med dvema orientirjema, oddaljenima 2 km, smo leteli 60 s.","60 na notranji skali postavi pod 20 (2 km) na zunanji.","Nad SEC preberi 12, kar je 120."],t.s)
B.Tb=new A.fT("Hitrost iz sekund (indeks SEC)","Za kratke odseke, merjene v sekundah.",!0,B.a6k,B.a2v,"GS = 120 km/h")
B.a2j=s(["Indeks \u25b260 postavi pod porabo na uro na zunanji skali.","Na notranji skali poi\u0161\u010di \u010das leta.","Nad njim na zunanji skali preberi porabljeno gorivo.","Obratno (poraba na uro): porabljeno gorivo na zunanji skali postavi nad \u010das na notranji, nad \u25b260 preberi porabo na uro."],t.s)
B.a_G=s(["Poraba 24 L/h, let traja 1 h 45 min (105 min).","\u25b260 postavi pod 24.","Nad 105 (1:45) na notranji skali preberi 42."],t.s)
B.Tg=new A.fT("Poraba goriva","gorivo = poraba na uro \xd7 \u010das",!0,B.a2j,B.a_G,"Gorivo = 42 L (brez rezerve)")
B.a01=s(["10 na notranji skali postavi pod drsno \u0161tevilo na zunanji.","Na notranji skali poi\u0161\u010di vi\u0161ino nad terenom.","Nad njo na zunanji skali preberi doseg v istih enotah kot vi\u0161ino.","Enako velja za vsako sorazmerje (npr. spust v m/s in hitrost)."],t.s)
B.a3I=s(["Drsno \u0161tevilo 30, vi\u0161ina nad terenom 600 m.","10 na notranji skali postavi pod 30.","Nad 60 (600 m) preberi 18, kar je 18 000 m."],t.s)
B.Te=new A.fT("Sorazmerja (drsno \u0161tevilo)","Doseg = drsno \u0161tevilo \xd7 vi\u0161ina",!0,B.a01,B.a3I,"Doseg \u2248 18 km (v mirnem zraku, brez rezerve)")
B.Yr=s(["Vrednost na notranji skali postavi pod pu\u0161\u010dico izhodne enote (npr. NAUT).","Pod pu\u0161\u010dico ciljne enote (npr. KM) na notranji skali preberi rezultat.","Pretvarja\u0161 lahko med enotami iste vrste: razdalja (NAUT, STAT, KM), prostornina (US GAL, IMP GAL, LITERS) in vi\u0161ina (FT, M)."],t.s)
B.a1R=s(["Koliko kilometrov je 50 NM?","50 na notranji skali postavi pod pu\u0161\u010dico NAUT.","Pod pu\u0161\u010dico KM preberi pribli\u017eno 92,6."],t.s)
B.Tn=new A.fT("Pretvorba enot","NAUT, STAT, KM, US GAL, IMP GAL, LITERS, FT, M",!0,B.Yr,B.a1R,"50 NM \u2248 92,6 km")
B.a0i=s(["Na spodnjem delu podlage sta skali \xb0C (notranja) in \xb0F (zunanja).","Poi\u0161\u010di vrednost na eni skali in preberi sosednjo vrednost na drugi."],t.s)
B.XQ=s(["+15 \xb0C stoji ob +59 \xb0F.","\u221210 \xb0C stoji ob +14 \xb0F."],t.s)
B.Td=new A.fT("Temperatura \xb0C \u2194 \xb0F","Skali na spodnjem delu podlage, disk ni potreben.",!0,B.a0i,B.XQ,"+15 \xb0C = +59 \xb0F")
B.a6W=s(["Na vi\u0161inomeru nastavi 1013 hPa in preberi tla\u010dno vi\u0161ino (PA).","V okencu za hitrost (POPRAVEK HITROSTI) zavrti disk, da je zunanja temperatura (AIR TEMP.) nasproti tla\u010dne vi\u0161ine.","Nad CAS na notranji skali preberi TAS na zunanji skali.","V okencu DENSITY ALT pod \u25b2 preberi gostotno vi\u0161ino."],t.s)
B.a5Z=s(["PA 2000 ft, OAT +30 \xb0C, CAS 100 km/h.","+30 v okencu postavi nasproti 2 (\xd71000 ft).","Nad 100 na notranji skali preberi pribli\u017eno 106.","Pod \u25b2 v okencu DENSITY ALT preberi pribli\u017eno 4,2 (\xd71000 ft)."],t.s)
B.Tc=new A.fT("Prava hitrost (TAS) in gostotna vi\u0161ina","Popravek CAS za tla\u010dno vi\u0161ino in temperaturo.",!0,B.a6W,B.a5Z,"TAS \u2248 106 km/h, gostotna vi\u0161ina \u2248 4200 ft")
B.XR=s(["V okencu za vi\u0161ino (POPRAVEK VI\u0160INE) zavrti disk, da je zunanja temperatura na vi\u0161ini leta nasproti tla\u010dne vi\u0161ine.","Nad kalibrirano (indicirano) vi\u0161ino na notranji skali preberi pravo vi\u0161ino na zunanji skali.","V hladnej\u0161em zraku od standardnega je prava vi\u0161ina ni\u017eja od indicirane, v toplej\u0161em vi\u0161ja."],t.s)
B.a5Q=s(["PA 6000 ft, OAT \u22125 \xb0C, indicirana vi\u0161ina 6000 ft.","\u22125 v okencu postavi nasproti 6 (\xd71000 ft).","Nad 60 na notranji skali preberi pribli\u017eno 58,2."],t.s)
B.Tf=new A.fT("Prava vi\u0161ina","Popravek vi\u0161ine za temperaturo zraka.",!0,B.XR,B.a5Q,"Prava vi\u0161ina \u2248 5820 ft (\u2248 180 ft ni\u017eje)")
B.a2a=s(["Smer vetra (od koder piha) zavrti pod TRUE INDEX.","Drsnik premakni, da je sredi\u0161\u010de na okrogli hitrosti (npr. 100).","Nad sredi\u0161\u010dem na sredinski \u010drti s tapom ozna\u010di hitrost vetra (pri 20 kt vetra oznaka pri 120).","Pravi kurz (TC) zavrti pod TRUE INDEX.","Drsnik premakni, da je oznaka na loku TAS.","Pod sredi\u0161\u010dem preberi GS.","Stopinje med sredinsko \u010drto in oznako so WCA: oznaka levo pomeni WCA levo, desno pomeni WCA desno.","TH = TC \u2212 WCA L oziroma TC + WCA R."],t.s)
B.a3i=s(["TC 090\xb0, TAS 100 kt, veter 030\xb0 / 20 kt.","030 pod TRUE INDEX, sredi\u0161\u010de na 100, oznaka pri 120.","090 pod TRUE INDEX, drsnik premakni, da je oznaka na loku 100.","Pod sredi\u0161\u010dem preberi pribli\u017eno 88, oznaka je 10\xb0 levo.","TH = 090\xb0 \u2212 10\xb0 = 080\xb0."],t.s)
B.Ti=new A.fT("Veter: GS in popravek za veter (WCA)","Iz TC, TAS in vetra dobi\u0161 GS in pravo glavo (TH).",!1,B.a2a,B.a3i,"GS \u2248 88 kt, WCA 10\xb0 L, TH = 080\xb0")
B.a3N=s(["Magnetni kurz: MC = TC \u2212 VAR E oziroma TC + VAR W (deklinacija s karte).","Magnetna glava: MH = MC \u2212 WCA L oziroma MC + WCA R (WCA iz vetrne strani).","Kompasna glava: CH = MH \xb1 DEV, deviacijo za MH preberi s tablice deviacije v letalu."],t.s)
B.a22=s(["TC 090\xb0, VAR 5\xb0 E, WCA 10\xb0 L, tablica deviacije: za 075\xb0 krmari 073\xb0.","MC = 090\xb0 \u2212 5\xb0 = 085\xb0.","MH = 085\xb0 \u2212 10\xb0 = 075\xb0.","CH = 075\xb0 \u2212 2\xb0 = 073\xb0."],t.s)
B.Tk=new A.fT("Od pravega do kompasnega kurza","TC \u2192 MC \u2192 MH \u2192 CH",!1,B.a3N,B.a22,"CH = 073\xb0")
